            .Select(entry => entry.AbilityId)
            .Order(StringComparer.Ordinal)
            .ToArray();
        var closureAbilityIds = TargetTypedActivatedAbilityOfficialFamilyClosureManifest
            .Select(entry => entry.AbilityId)
