            && string.Equals(entry.ConcreteFollowupGateId, "A_CONFORMANCE_AUTOMATED_TEST_EVIDENCE_CARD_MATRIX_BLOCKER_CLOSURE_POST_03EG_E", StringComparison.Ordinal));
