        Assert.Equal(Post03HoCardMatrixReadinessPaymentCostHostileTakeoverControlReadyTargetingStackBlockerClosureCandidateGate, manifest.GateId);
        Assert.Equal("E_CARD_MATRIX_READINESS", manifest.DownstreamOwner);
        Assert.Equal(Post03HoCardMatrixReadinessPaymentCostHostileTakeoverControlReadyTargetingStackBlockerClosureCandidate, manifest.Classification);
        Assert.Equal(nameof(Post03HnCardMatrixReadinessPaymentCostBulletTimeDamagePowerSpentTargetingStackBlockerClosureCandidateManifest), manifest.InputIsolatedDiffVerifierManifest);
