        var functionalUnits = root.GetProperty("functionalUnits").EnumerateArray().ToArray();
        var snapshotEntries = root.GetProperty("snapshotEntries").EnumerateArray().ToArray();
        var closureCandidate = root.GetProperty("stage4D03LsPaymentCostSandcraftEchoTokenFaqTargetingStackBlockerClosureCandidate");
        var rowCountContinuity = closureCandidate.GetProperty("rowCountContinuity");
        var selectedRowTransition = closureCandidate.GetProperty("selectedRowTransition");
        var writeScope = closureCandidate.GetProperty("writeScope");
        var manifest = Assert.Single(Post03LsCardMatrixReadinessPaymentCostSandcraftEchoTokenFaqTargetingStackBlockerClosureCandidateManifest);
        var selectedFunctionalUnit = Assert.Single(functionalUnits, unit =>
            string.Equals(unit.GetProperty("functionalUnitId").GetString(), manifest.SelectedFunctionalUnitId, StringComparison.Ordinal));
        var selectedSnapshots = snapshotEntries
            .Where(entry => string.Equals(entry.GetProperty("functionalUnitId").GetString(), manifest.SelectedFunctionalUnitId, StringComparison.Ordinal))
            .ToArray();

        Assert.Equal("4D-03LS-E", closureCandidate.GetProperty("stage").GetString());
        Assert.Equal(Post03LsCardMatrixReadinessPaymentCostSandcraftEchoTokenFaqTargetingStackBlockerClosureCandidate, closureCandidate.GetProperty("classification").GetString());
        Assert.Equal(Post03LsCardMatrixReadinessPaymentCostSandcraftEchoTokenFaqTargetingStackBlockerClosureCandidateGate, closureCandidate.GetProperty("gate").GetString());
        Assert.Equal(nameof(Post03LrCardMatrixReadinessPaymentCostArionsFallEquipmentFaqLayerBlockerClosureCandidateManifest), closureCandidate.GetProperty("inputPreviousClosureCandidateManifest").GetString());
        Assert.Equal("payment-and-targeting-stack-timing", closureCandidate.GetProperty("selectedSecondaryMatrixRowQuery").GetString());
        Assert.Equal("FU-7bfb48b83e", manifest.SelectedFunctionalUnitId);
        Assert.Equal("SFD·031/221", manifest.SelectedCardNo);
        Assert.Equal("点沙成兵", manifest.SelectedCardName);
        Assert.Equal("SANDCRAFT_CREATE_SAND_SOLDIER_ECHO", manifest.SelectedEffectKind);

        Assert.Equal(360, CountPost03EeMatrixRows(functionalUnits, "payment-cost"));
        Assert.Equal(446, CountPost03EeMatrixRows(snapshotEntries, "payment-cost"));
        Assert.Equal(34, CountPost03EfMatrixRowsWithBlocker(functionalUnits, "payment-cost", "NEEDS_ENGINE_SUPPORT"));
        Assert.Equal(328, CountPost03EfMatrixRowsWithBlocker(functionalUnits, "payment-cost", "NEEDS_AUTOMATED_TEST_EVIDENCE"));
        Assert.Equal(92, CountPost03EfMatrixRowsWithBlocker(functionalUnits, "payment-cost", "NEEDS_FAQ_REVIEW"));
        Assert.Equal(0, CountPost03EpPaymentCostRowsByStage4BFreezeStatus(functionalUnits, "NEEDS_ENGINE_SUPPORT"));
        Assert.Equal(61, CountPost03EpPaymentCostRowsByStage4BFreezeStatus(functionalUnits, "NEEDS_FAQ_REVIEW"));
        Assert.Equal(208, CountPost03EfMatrixRowsWithBlocker(functionalUnits, "payment-or-targeting-stack-timing", "NEEDS_ENGINE_SUPPORT"));
        Assert.Equal(20, CountPost03EfMatrixRowsWithBlocker(functionalUnits, "payment-and-targeting-stack-timing", "NEEDS_ENGINE_SUPPORT"));

        Assert.Equal(196, rowCountContinuity.GetProperty("needsEngineSupportFunctionalUnitsBefore").GetInt32());
        Assert.Equal(195, rowCountContinuity.GetProperty("needsEngineSupportFunctionalUnitsAfter").GetInt32());
        Assert.Equal(136, rowCountContinuity.GetProperty("primaryNeedsEngineSupportBefore").GetInt32());
        Assert.Equal(136, rowCountContinuity.GetProperty("primaryNeedsEngineSupportAfter").GetInt32());
        Assert.Equal(383, rowCountContinuity.GetProperty("paymentOrTargetingStackTimingNeedsEngineSupportBefore").GetInt32());
        Assert.Equal(382, rowCountContinuity.GetProperty("paymentOrTargetingStackTimingNeedsEngineSupportAfter").GetInt32());
        Assert.Equal(123, rowCountContinuity.GetProperty("paymentAndTargetingStackTimingNeedsEngineSupportBefore").GetInt32());
        Assert.Equal(122, rowCountContinuity.GetProperty("paymentAndTargetingStackTimingNeedsEngineSupportAfter").GetInt32());
        Assert.Equal(328, rowCountContinuity.GetProperty("needsAutomatedTestEvidenceAfter").GetInt32());
        Assert.Equal(92, rowCountContinuity.GetProperty("needsFaqReviewAfter").GetInt32());
        Assert.Equal(0, rowCountContinuity.GetProperty("fullOfficialTrueAfter").GetInt32());
        Assert.False(rowCountContinuity.GetProperty("readyAfter").GetBoolean());

        Assert.Equal("NEEDS_FAQ_REVIEW", selectedRowTransition.GetProperty("beforeFreezeStatus").GetString());
        Assert.Equal("NEEDS_FAQ_REVIEW", selectedRowTransition.GetProperty("afterFreezeStatus").GetString());
        Assert.True(writeScope.GetProperty("isolatedToPaymentCostRow").GetBoolean());
        Assert.True(writeScope.GetProperty("affectedTargetingStackTimingRow").GetBoolean());
        Assert.True(writeScope.GetProperty("affectedPaymentOrTargetingStackTimingRow").GetBoolean());
        Assert.True(writeScope.GetProperty("affectedPaymentAndTargetingStackTimingRow").GetBoolean());
        Assert.Equal(1, writeScope.GetProperty("functionalUnitsChanged").GetInt32());
        Assert.Equal(1, writeScope.GetProperty("snapshotEntriesChanged").GetInt32());
        Assert.False(writeScope.GetProperty("stage4BFreezeStatusChanged").GetBoolean());
        Assert.True(writeScope.GetProperty("stage4BStatusFlagsChanged").GetBoolean());
        Assert.False(writeScope.GetProperty("runtimeChanged").GetBoolean());
        Assert.False(writeScope.GetProperty("frontendChanged").GetBoolean());
        Assert.False(writeScope.GetProperty("protocolCoreFieldsChanged").GetBoolean());
        Assert.False(writeScope.GetProperty("officialCatalogChanged").GetBoolean());

        var selectedStage4B = selectedFunctionalUnit.GetProperty("stage4B");
        Assert.Equal("NEEDS_FAQ_REVIEW", selectedStage4B.GetProperty("freezeStatus").GetString());
        Assert.False(HasStringArrayValue(selectedStage4B, "statusFlags", "NEEDS_ENGINE_SUPPORT"));
        Assert.True(HasStringArrayValue(selectedStage4B, "statusFlags", "IMPLEMENTED_UNTESTED"));
        Assert.True(HasStringArrayValue(selectedStage4B, "statusFlags", "NEEDS_FAQ_REVIEW"));
        Assert.False(HasStringArrayValue(selectedStage4B, "fullOfficialBlockers", "NEEDS_ENGINE_SUPPORT"));
        Assert.True(HasStringArrayValue(selectedStage4B, "fullOfficialBlockers", "NEEDS_AUTOMATED_TEST_EVIDENCE"));
        Assert.True(HasStringArrayValue(selectedStage4B, "fullOfficialBlockers", "NEEDS_FAQ_REVIEW"));
        Assert.False(selectedStage4B.GetProperty("fullOfficial").GetBoolean());

        Assert.Single(selectedSnapshots);
        Assert.All(selectedSnapshots, snapshot =>
        {
            var snapshotStage4B = snapshot.GetProperty("stage4B");
            Assert.Equal("NEEDS_FAQ_REVIEW", snapshotStage4B.GetProperty("freezeStatus").GetString());
            Assert.False(HasStringArrayValue(snapshotStage4B, "statusFlags", "NEEDS_ENGINE_SUPPORT"));
            Assert.True(HasStringArrayValue(snapshotStage4B, "statusFlags", "IMPLEMENTED_UNTESTED"));
            Assert.True(HasStringArrayValue(snapshotStage4B, "statusFlags", "NEEDS_FAQ_REVIEW"));
            Assert.False(snapshotStage4B.GetProperty("fullOfficial").GetBoolean());
        });

        Assert.Contains("Sandcraft automated evidence disposition remains open", manifest.NonClosureStatus, StringComparison.Ordinal);
        Assert.Contains("Sandcraft FAQ adjudication remains open", manifest.NonClosureStatus, StringComparison.Ordinal);
        Assert.Contains("Sandcraft complete Echo optional-cost/repeat breadth remains open", manifest.NonClosureStatus, StringComparison.Ordinal);
        Assert.Contains("Sandcraft complete token creation breadth remains open", manifest.NonClosureStatus, StringComparison.Ordinal);
        Assert.Contains("complete PaymentEngine / PAY_COST matrix remains open", manifest.NonClosureStatus, StringComparison.Ordinal);
        Assert.Contains("READY remains open", manifest.NonClosureStatus, StringComparison.Ordinal);
        Assert.All(manifest.DocAnchors, anchor => Assert.True(File.Exists(Path.Combine(repositoryRoot, anchor)), anchor));
    }

