        Assert.False(rowCountContinuity.GetProperty("readyAfter").GetBoolean());

        Assert.Equal("SHARED_ORACLE_IMPLEMENTATION", selectedRowTransition.GetProperty("beforeFreezeStatus").GetString());
        Assert.Equal("SHARED_ORACLE_IMPLEMENTATION", selectedRowTransition.GetProperty("afterFreezeStatus").GetString());
