        Assert.Contains("selected/ready power-modifier duration remains open", manifest.NonClosureStatus, StringComparison.Ordinal);
        Assert.Contains("cleanup/replacement-duration breadth remains open", manifest.NonClosureStatus, StringComparison.Ordinal);
        Assert.Contains("complete FEPR target/stack lifecycle breadth remains open", manifest.NonClosureStatus, StringComparison.Ordinal);
        Assert.Contains("complete PaymentEngine / PAY_COST matrix remains open", manifest.NonClosureStatus, StringComparison.Ordinal);
        Assert.Contains("READY remains open", manifest.NonClosureStatus, StringComparison.Ordinal);
        Assert.All(manifest.DocAnchors, anchor => Assert.True(File.Exists(Path.Combine(repositoryRoot, anchor)), anchor));
    }

