        Assert.Equal("payment-cost-faq-layer-targeting-stack", closureCandidate.GetProperty("selectedSecondaryMatrixRowQuery").GetString());
        Assert.Equal("FU-5dd917877b", manifest.SelectedFunctionalUnitId);
        Assert.Equal("SFD·068/221", manifest.SelectedCardNo);
        Assert.Equal("机械迷", manifest.SelectedCardName);
        Assert.Equal("MECH_MANIAC_PLAY_UNIT_NO_OPTIONAL_HASTE", manifest.SelectedEffectKind);

        Assert.Equal(360, CountPost03EeMatrixRows(functionalUnits, "payment-cost"));
        Assert.Equal(446, CountPost03EeMatrixRows(snapshotEntries, "payment-cost"));
        Assert.Equal(34, CountPost03EfMatrixRowsWithBlocker(functionalUnits, "payment-cost", "NEEDS_ENGINE_SUPPORT"));
        Assert.Equal(328, CountPost03EfMatrixRowsWithBlocker(functionalUnits, "payment-cost", "NEEDS_AUTOMATED_TEST_EVIDENCE"));
