        Assert.Equal(181, rowCountContinuity.GetProperty("needsEngineSupportFunctionalUnitsBefore").GetInt32());
        Assert.Equal(180, rowCountContinuity.GetProperty("needsEngineSupportFunctionalUnitsAfter").GetInt32());
        Assert.Equal(132, rowCountContinuity.GetProperty("primaryNeedsEngineSupportBefore").GetInt32());
        Assert.Equal(132, rowCountContinuity.GetProperty("primaryNeedsEngineSupportAfter").GetInt32());
        Assert.Equal(368, rowCountContinuity.GetProperty("paymentOrTargetingStackTimingNeedsEngineSupportBefore").GetInt32());
        Assert.Equal(367, rowCountContinuity.GetProperty("paymentOrTargetingStackTimingNeedsEngineSupportAfter").GetInt32());
