            Assert.Equal(entry.HiddenAfter, rowCountContinuity.GetProperty("hiddenInfoRandomZoneNeedsEngineSupportAfter").GetInt32());
            Assert.Equal(entry.PaymentOrBefore, rowCountContinuity.GetProperty("paymentOrTargetingStackTimingNeedsEngineSupportBefore").GetInt32());
            Assert.Equal(entry.PaymentOrAfter, rowCountContinuity.GetProperty("paymentOrTargetingStackTimingNeedsEngineSupportAfter").GetInt32());
