    [Fact]
    public void PaymentEnginePost03OgThrough03OiCardMatrixReadinessPaymentCostSfdSharedOracleEvidenceBundleReducesThreeEngineSupportBlockers()
    {
        var repositoryRoot = ResolveRepositoryRoot();
        var matrixPath = Path.Combine(repositoryRoot, "docs", "CURRENT_CARD_EFFECT_COVERAGE_MATRIX_SKELETON.json");
        using var document = JsonDocument.Parse(File.ReadAllText(matrixPath));
        var root = document.RootElement;
        var functionalUnits = root.GetProperty("functionalUnits").EnumerateArray().ToArray();
        var snapshotEntries = root.GetProperty("snapshotEntries").EnumerateArray().ToArray();
        var cases = new (string PropertyName, string Stage, string Classification, string Gate, string InputPreviousManifest, string SecondaryRowQuery, string FunctionalUnitId, string CardNo, string CardName, string EffectKind, int NeedsBefore, int NeedsAfter, int PrimaryBefore, int PrimaryAfter, int AllBefore, int AllAfter, int TargetingBefore, int TargetingAfter, int CleanupBefore, int CleanupAfter, int HiddenBefore, int HiddenAfter, int PaymentOrBefore, int PaymentOrAfter, int PaymentAndBefore, int PaymentAndAfter, int ExpectedSnapshotRows, string[] ExpectedCategories, string[] RequiredNonClosurePhrases)[]
        {
            ("stage4D03OgPaymentCostSfdLucianNoOptionalAssembleLayerTargetingStackBlockerClosureCandidate", "4D-03OG-E", "post-03of-e-card-matrix-readiness-payment-cost-sfd-lucian-no-optional-assemble-layer-targeting-stack-blocker-closure-candidate", "E_CARD_MATRIX_READINESS_POST_03OF_PAYMENT_COST_SFD_LUCIAN_NO_OPTIONAL_ASSEMBLE_LAYER_TARGETING_STACK_BLOCKER_CLOSURE_CANDIDATE", "Post03OfCardMatrixReadinessPaymentCostQuicksandPitDestroyBattlefieldUnitBattleCleanupHiddenTargetingStackBlockerClosureCandidateManifest", "payment-cost-sfd-lucian-no-optional-assemble-layer-targeting-stack", "FU-de2dbad3c5", "SFD·113/221", "卢锡安", "SFD_LUCIAN_ALT_A_NO_OPTIONAL_ASSEMBLE_PLAY_UNIT;SFD_LUCIAN_NO_OPTIONAL_ASSEMBLE_PLAY_UNIT", 130, 129, 90, 90, 528, 527, 273, 272, 208, 208, 170, 170, 317, 316, 86, 85, 2, new[] { "battle-spell-duel", "layer-continuous-effect", "payment-cost", "targeting-stack-timing" }, new[] { "Lucian automated evidence disposition remains open", "Tempered assemble / armament attach breadth remains open", "READY remains open" }),
            ("stage4D03OhPaymentCostSfdYoneNoOptionalAssembleLayerTargetingStackBlockerClosureCandidate", "4D-03OH-E", "post-03og-e-card-matrix-readiness-payment-cost-sfd-yone-no-optional-assemble-layer-targeting-stack-blocker-closure-candidate", "E_CARD_MATRIX_READINESS_POST_03OG_PAYMENT_COST_SFD_YONE_NO_OPTIONAL_ASSEMBLE_LAYER_TARGETING_STACK_BLOCKER_CLOSURE_CANDIDATE", "Post03OgCardMatrixReadinessPaymentCostSfdLucianNoOptionalAssembleLayerTargetingStackBlockerClosureCandidateManifest", "payment-cost-sfd-yone-no-optional-assemble-layer-targeting-stack", "FU-d1c30c4216", "SFD·116/221", "永恩", "SFD_YONE_PLAY_NO_OPTIONAL_ASSEMBLE;SFD_YONE_PRECON_NO_OPTIONAL_ASSEMBLE_PLAY_UNIT;SFD_YONE_PROMO_PLAY_NO_OPTIONAL_ASSEMBLE", 129, 128, 90, 90, 527, 526, 272, 271, 208, 208, 170, 170, 316, 315, 85, 84, 3, new[] { "battle-spell-duel", "layer-continuous-effect", "payment-cost", "targeting-stack-timing" }, new[] { "Yone automated evidence disposition remains open", "Tempered assemble / armament attach breadth remains open", "READY remains open" }),
            ("stage4D03OiPaymentCostSfdSivirSpellshield2KeywordUnitBattleTargetingStackBlockerClosureCandidate", "4D-03OI-E", "post-03oh-e-card-matrix-readiness-payment-cost-sfd-sivir-spellshield2-keyword-unit-battle-targeting-stack-blocker-closure-candidate", "E_CARD_MATRIX_READINESS_POST_03OH_PAYMENT_COST_SFD_SIVIR_SPELLSHIELD2_KEYWORD_UNIT_BATTLE_TARGETING_STACK_BLOCKER_CLOSURE_CANDIDATE", "Post03OhCardMatrixReadinessPaymentCostSfdYoneNoOptionalAssembleLayerTargetingStackBlockerClosureCandidateManifest", "payment-cost-sfd-sivir-spellshield2-keyword-unit-battle-targeting-stack", "FU-83471f1082", "SFD·120/221", "希维尔", "SFD_SIVIR_ALT_A_SPELLSHIELD2_PLAY_KEYWORD_UNIT;SFD_SIVIR_SPELLSHIELD2_PLAY_KEYWORD_UNIT", 128, 127, 90, 90, 526, 525, 271, 270, 208, 208, 170, 170, 315, 314, 84, 83, 2, new[] { "battle-spell-duel", "payment-cost", "targeting-stack-timing" }, new[] { "Sivir automated evidence disposition remains open", "Spellshield2 target-tax breadth remains open", "READY remains open" })
        };

        Assert.Equal(811, functionalUnits.Length);
        Assert.Equal(1009, snapshotEntries.Length);
        Assert.Equal(415, CountPost03EfMatrixRowsWithBlocker(functionalUnits, "all-functional-units", "NEEDS_ENGINE_SUPPORT"));
        Assert.Equal(360, CountPost03EeMatrixRows(functionalUnits, "payment-cost"));
        Assert.Equal(446, CountPost03EeMatrixRows(snapshotEntries, "payment-cost"));
        Assert.Equal(34, CountPost03EfMatrixRowsWithBlocker(functionalUnits, "payment-cost", "NEEDS_ENGINE_SUPPORT"));
        Assert.Equal(328, CountPost03EfMatrixRowsWithBlocker(functionalUnits, "payment-cost", "NEEDS_AUTOMATED_TEST_EVIDENCE"));
        Assert.Equal(92, CountPost03EfMatrixRowsWithBlocker(functionalUnits, "payment-cost", "NEEDS_FAQ_REVIEW"));
        Assert.Equal(0, CountPost03EpPaymentCostRowsByStage4BFreezeStatus(functionalUnits, "NEEDS_ENGINE_SUPPORT"));
        Assert.Equal(61, CountPost03EpPaymentCostRowsByStage4BFreezeStatus(functionalUnits, "NEEDS_FAQ_REVIEW"));
        Assert.Equal(194, functionalUnits.Count(unit => HasStringArrayValue(unit, "uncoveredEffectCategories", "targeting-stack-timing") && HasStage4BBlocker(unit, "NEEDS_ENGINE_SUPPORT")));
        Assert.Equal(155, functionalUnits.Count(unit => HasStringArrayValue(unit, "uncoveredEffectCategories", "cleanup-replacement-duration") && HasStage4BBlocker(unit, "NEEDS_ENGINE_SUPPORT")));
        Assert.Equal(141, functionalUnits.Count(unit => HasStringArrayValue(unit, "uncoveredEffectCategories", "hidden-info-random-zone") && HasStage4BBlocker(unit, "NEEDS_ENGINE_SUPPORT")));
        Assert.Equal(208, CountPost03EfMatrixRowsWithBlocker(functionalUnits, "payment-or-targeting-stack-timing", "NEEDS_ENGINE_SUPPORT"));
        Assert.Equal(20, CountPost03EfMatrixRowsWithBlocker(functionalUnits, "payment-and-targeting-stack-timing", "NEEDS_ENGINE_SUPPORT"));

        foreach (var entry in cases)
        {
            var closureCandidate = root.GetProperty(entry.PropertyName);
            var rowCountContinuity = closureCandidate.GetProperty("rowCountContinuity");
            var selectedRowTransition = closureCandidate.GetProperty("selectedRowTransition");
            var writeScope = closureCandidate.GetProperty("writeScope");
            var selectedFunctionalUnit = Assert.Single(functionalUnits, unit => string.Equals(unit.GetProperty("functionalUnitId").GetString(), entry.FunctionalUnitId, StringComparison.Ordinal));
            var selectedSnapshots = snapshotEntries.Where(snapshot => string.Equals(snapshot.GetProperty("functionalUnitId").GetString(), entry.FunctionalUnitId, StringComparison.Ordinal)).ToArray();

            Assert.Equal(entry.Stage, closureCandidate.GetProperty("stage").GetString());
            Assert.Equal(entry.Classification, closureCandidate.GetProperty("classification").GetString());
            Assert.Equal(entry.Gate, closureCandidate.GetProperty("gate").GetString());
            Assert.Equal(entry.InputPreviousManifest, closureCandidate.GetProperty("inputPreviousClosureCandidateManifest").GetString());
            Assert.Equal(entry.SecondaryRowQuery, closureCandidate.GetProperty("selectedSecondaryMatrixRowQuery").GetString());
            Assert.Equal(entry.FunctionalUnitId, closureCandidate.GetProperty("selectedFunctionalUnitId").GetString());
            Assert.Equal(entry.CardNo, closureCandidate.GetProperty("selectedCardNo").GetString());
            Assert.Equal(entry.CardName, closureCandidate.GetProperty("selectedCardName").GetString());
            Assert.Equal(entry.EffectKind, closureCandidate.GetProperty("selectedEffectKind").GetString());
            Assert.Equal(entry.NeedsBefore, rowCountContinuity.GetProperty("needsEngineSupportFunctionalUnitsBefore").GetInt32());
            Assert.Equal(entry.NeedsAfter, rowCountContinuity.GetProperty("needsEngineSupportFunctionalUnitsAfter").GetInt32());
            Assert.Equal(entry.PrimaryBefore, rowCountContinuity.GetProperty("primaryNeedsEngineSupportBefore").GetInt32());
            Assert.Equal(entry.PrimaryAfter, rowCountContinuity.GetProperty("primaryNeedsEngineSupportAfter").GetInt32());
            Assert.Equal(entry.AllBefore, rowCountContinuity.GetProperty("allFunctionalUnitsNeedsEngineSupportBefore").GetInt32());
            Assert.Equal(entry.AllAfter, rowCountContinuity.GetProperty("allFunctionalUnitsNeedsEngineSupportAfter").GetInt32());
            Assert.Equal(entry.TargetingBefore, rowCountContinuity.GetProperty("targetingStackTimingNeedsEngineSupportBefore").GetInt32());
            Assert.Equal(entry.TargetingAfter, rowCountContinuity.GetProperty("targetingStackTimingNeedsEngineSupportAfter").GetInt32());
            Assert.Equal(entry.CleanupBefore, rowCountContinuity.GetProperty("cleanupReplacementDurationNeedsEngineSupportBefore").GetInt32());
            Assert.Equal(entry.CleanupAfter, rowCountContinuity.GetProperty("cleanupReplacementDurationNeedsEngineSupportAfter").GetInt32());
            Assert.Equal(entry.HiddenBefore, rowCountContinuity.GetProperty("hiddenInfoRandomZoneNeedsEngineSupportBefore").GetInt32());
            Assert.Equal(entry.HiddenAfter, rowCountContinuity.GetProperty("hiddenInfoRandomZoneNeedsEngineSupportAfter").GetInt32());
            Assert.Equal(entry.PaymentOrBefore, rowCountContinuity.GetProperty("paymentOrTargetingStackTimingNeedsEngineSupportBefore").GetInt32());
            Assert.Equal(entry.PaymentOrAfter, rowCountContinuity.GetProperty("paymentOrTargetingStackTimingNeedsEngineSupportAfter").GetInt32());
            Assert.Equal(entry.PaymentAndBefore, rowCountContinuity.GetProperty("paymentAndTargetingStackTimingNeedsEngineSupportBefore").GetInt32());
            Assert.Equal(entry.PaymentAndAfter, rowCountContinuity.GetProperty("paymentAndTargetingStackTimingNeedsEngineSupportAfter").GetInt32());
            Assert.Equal(328, rowCountContinuity.GetProperty("needsAutomatedTestEvidenceAfter").GetInt32());
            Assert.Equal(92, rowCountContinuity.GetProperty("needsFaqReviewAfter").GetInt32());
            Assert.Equal(0, rowCountContinuity.GetProperty("fullOfficialTrueAfter").GetInt32());
            Assert.False(rowCountContinuity.GetProperty("readyAfter").GetBoolean());

            Assert.Equal("SHARED_ORACLE_IMPLEMENTATION", selectedRowTransition.GetProperty("beforeFreezeStatus").GetString());
            Assert.Equal("SHARED_ORACLE_IMPLEMENTATION", selectedRowTransition.GetProperty("afterFreezeStatus").GetString());
            Assert.Equal(1, writeScope.GetProperty("functionalUnitsChanged").GetInt32());
            Assert.Equal(entry.ExpectedSnapshotRows, writeScope.GetProperty("snapshotEntriesChanged").GetInt32());
            Assert.False(writeScope.GetProperty("stage4BFreezeStatusChanged").GetBoolean());
            Assert.True(writeScope.GetProperty("stage4BStatusFlagsChanged").GetBoolean());
            Assert.False(writeScope.GetProperty("runtimeChanged").GetBoolean());
            Assert.False(writeScope.GetProperty("frontendChanged").GetBoolean());
            Assert.False(writeScope.GetProperty("protocolCoreFieldsChanged").GetBoolean());
            Assert.False(writeScope.GetProperty("officialCatalogChanged").GetBoolean());

            var selectedStage4B = selectedFunctionalUnit.GetProperty("stage4B");
            Assert.Equal("SHARED_ORACLE_IMPLEMENTATION", selectedStage4B.GetProperty("freezeStatus").GetString());
            foreach (var category in entry.ExpectedCategories)
            {
                Assert.True(HasStringArrayValue(selectedFunctionalUnit, "uncoveredEffectCategories", category));
            }

            Assert.False(HasStringArrayValue(selectedStage4B, "statusFlags", "NEEDS_ENGINE_SUPPORT"));
            Assert.True(HasStringArrayValue(selectedStage4B, "statusFlags", "IMPLEMENTED_UNTESTED"));
            Assert.True(HasStringArrayValue(selectedStage4B, "statusFlags", "SHARED_ORACLE_IMPLEMENTATION"));
            Assert.False(HasStringArrayValue(selectedStage4B, "fullOfficialBlockers", "NEEDS_ENGINE_SUPPORT"));
            Assert.True(HasStringArrayValue(selectedStage4B, "fullOfficialBlockers", "NEEDS_AUTOMATED_TEST_EVIDENCE"));
            Assert.False(selectedStage4B.GetProperty("fullOfficial").GetBoolean());

            Assert.Equal(entry.ExpectedSnapshotRows, selectedSnapshots.Length);
            foreach (var selectedSnapshot in selectedSnapshots)
            {
                var snapshotStage4B = selectedSnapshot.GetProperty("stage4B");
                Assert.Equal("SHARED_ORACLE_IMPLEMENTATION", snapshotStage4B.GetProperty("freezeStatus").GetString());
                Assert.False(HasStringArrayValue(snapshotStage4B, "statusFlags", "NEEDS_ENGINE_SUPPORT"));
                Assert.True(HasStringArrayValue(snapshotStage4B, "statusFlags", "IMPLEMENTED_UNTESTED"));
                Assert.True(HasStringArrayValue(snapshotStage4B, "statusFlags", "SHARED_ORACLE_IMPLEMENTATION"));
                Assert.False(snapshotStage4B.GetProperty("fullOfficial").GetBoolean());
            }

            var nonClosureStatus = closureCandidate.GetProperty("nonClosureStatus").GetString() ?? string.Empty;
            foreach (var phrase in entry.RequiredNonClosurePhrases)
            {
                Assert.Contains(phrase, nonClosureStatus, StringComparison.Ordinal);
            }
        }
    }

